package vn.boardinghub.modules.audit;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class AuditService{private final AuditRepository repo;public AuditService(AuditRepository r){repo=r;}@Transactional public void record(String actor,String action,String type,String id,String detail){repo.save(new AuditLog(actor,action,type,id,detail));}}
